import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

public class BoundedService {
    private final Semaphore permits;

    public BoundedService(int maxConcurrent) {
        // Non-fair by default: higher throughput, possible barging.
        // Use true for FIFO when ordering matters more than raw throughput.
        this.permits = new Semaphore(maxConcurrent);
    }

    public String callDownstream(String req) throws Exception {
        // Bounded wait: shed load instead of queuing forever.
        // Trade-off: caller gets fast failure, needs a fallback.
        boolean acquired = permits.tryAcquire(200, TimeUnit.MILLISECONDS);
        if (!acquired) {
            throw new OverloadedException("shed: no permit within 200ms");
        }
        try {
            return downstream(req); // only N threads can be here
        } finally {
            permits.release(); // exactly once, only because acquired == true
        }
    }

    private String downstream(String req) { return "ok:" + req; }
    static class OverloadedException extends Exception {
        OverloadedException(String m) { super(m); }
    }
}

public class SimpleSemaphore {
    private int permits;

    public SimpleSemaphore(int initial) {
        if (initial < 0) throw new IllegalArgumentException("permits < 0");
        this.permits = initial;
    }

    public synchronized void acquire() throws InterruptedException {
        while (permits == 0) {
            wait(); // loop: guards against spurious wakeup
        }
        permits--;
    }

    public synchronized void release() {
        permits++;
        notifyAll(); // notify wakes one; notifyAll is simpler, costlier
    }

    public synchronized boolean tryAcquire() {
        if (permits == 0) return false;
        permits--;
        return true;
    }
}
